def countEscapingStarts(nums):
    n = len(nums)
    state = [0] * n  # 0 new, 1 on the current path, 2 escapes, 3 loops
    for s in range(n):
        if state[s]:
            continue
        path = []
        u = s
        while True:
            if u < 0 or u >= n:
                verdict = 2
                break
            if state[u] == 1:
                verdict = 3
                break
            if state[u] >= 2:
                verdict = state[u]
                break
            state[u] = 1
            path.append(u)
            u += nums[u]
        for v in path:
            state[v] = verdict
    return sum(1 for v in state if v == 2)
